mkdir -p deploy .github/workflows && cat > Dockerfile <<'EOF'
# syntax=docker/dockerfile:1

# ---- Build stage: compile the Astro site to static files ----
FROM node:22-alpine AS build
WORKDIR /app

# Canonical public URL of the site (used for RSS links / Astro.site).
ARG SITE_URL
ENV SITE_URL=${SITE_URL}

COPY package.json package-lock.json ./
RUN npm ci --no-audit --no-fund

COPY . .
RUN npm run build

# ---- Runtime stage: serve the static files with nginx (non-root) ----
FROM nginxinc/nginx-unprivileged:stable-alpine AS runtime

COPY deploy/nginx.conf /etc/nginx/conf.d/default.conf
COPY deploy/security-headers.conf /etc/nginx/snippets/security-headers.conf
COPY --from=build /app/dist /usr/share/nginx/html

EXPOSE 8080
# nginx runs in the foreground as PID 1; if it exits, the platform restarts the container.
CMD ["nginx", "-g", "daemon off;"]
EOF
cat > .dockerignore <<'EOF'
node_modules
dist
.astro
.git
.github
.vscode
.env
.env.*
npm-debug.log*
fly.toml
Dockerfile
.dockerignore
EOF
cat > deploy/security-headers.conf <<'EOF'
# Included in every location block, because nginx drops server-level
# add_header directives in any location that defines its own add_header.
add_header Strict-Transport-Security "max-age=31536000" always;
add_header X-Content-Type-Options "nosniff" always;
add_header X-Frame-Options "DENY" always;
add_header Referrer-Policy "strict-origin-when-cross-origin" always;
EOF
cat > deploy/nginx.conf <<'EOF'
# One JSON object per request on stdout, so `fly logs` is easy to read and grep.
# Fly's edge proxy terminates TLS; the real client IP arrives in Fly-Client-IP.
log_format json_access escape=json
  '{"time":"$time_iso8601",'
  '"client_ip":"$http_fly_client_ip",'
  '"method":"$request_method",'
  '"host":"$host",'
  '"path":"$request_uri",'
  '"status":$status,'
  '"bytes":$body_bytes_sent,'
  '"duration_s":$request_time,'
  '"referer":"$http_referer",'
  '"user_agent":"$http_user_agent",'
  '"fly_request_id":"$http_fly_request_id"}';

server {
    listen 8080;
    listen [::]:8080;
    server_name _;

    root /usr/share/nginx/html;
    index index.html;

    access_log /dev/stdout json_access;
    error_log  /dev/stderr warn;

    server_tokens off;
    # Behind a proxy, never put the internal port (8080) or scheme in redirects.
    absolute_redirect off;

    gzip on;
    gzip_vary on;
    gzip_min_length 512;
    gzip_types text/css application/javascript application/json image/svg+xml
               application/rss+xml application/xml text/xml text/plain;

    # Health check for the platform. Not logged, to keep logs useful.
    location = /healthz {
        access_log off;
        default_type text/plain;
        return 200 "ok\n";
    }

    # Astro's build output has content hashes in the file names, so it's safe to cache forever.
    location /_astro/ {
        include /etc/nginx/snippets/security-headers.conf;
        add_header Cache-Control "public, max-age=31536000, immutable" always;
        try_files $uri =404;
    }

    location / {
        include /etc/nginx/snippets/security-headers.conf;
        # HTML and other files: browsers revalidate, so new deploys show up immediately.
        add_header Cache-Control "public, max-age=0, must-revalidate" always;
        try_files $uri $uri/index.html $uri.html =404;
    }

    error_page 404 /404.html;
    location = /404.html {
        internal;
        include /etc/nginx/snippets/security-headers.conf;
        add_header Cache-Control "no-cache" always;
    }
}
EOF
cat > fly.toml <<'EOF'
# Fly.io configuration. Reference: https://fly.io/docs/reference/configuration/
#
# TODO before first deploy: set `app` to a globally unique name, and set
# SITE_URL below to your custom domain. See DEPLOY.md.
app = "astro-blog-CHANGE-ME"
primary_region = "iad"

[build]
  dockerfile = "Dockerfile"

  [build.args]
    SITE_URL = "https://blog.example.com"

[deploy]
  strategy = "rolling"

[http_service]
  internal_port = 8080
  force_https = true            # HTTP -> HTTPS redirect at Fly's edge
  # Keep machines running all the time. Real users never wait on a cold start.
  auto_stop_machines = "off"
  auto_start_machines = true
  min_machines_running = 1

  [http_service.concurrency]
    type = "requests"
    soft_limit = 500
    hard_limit = 1000

  # Fly's proxy stops sending traffic to a machine that fails this check.
  [[http_service.checks]]
    grace_period = "10s"
    interval = "15s"
    timeout = "2s"
    method = "GET"
    path = "/healthz"

# If nginx (PID 1) exits for any reason, restart the machine.
[[restart]]
  policy = "always"
  retries = 10

[[vm]]
  size = "shared-cpu-1x"
  memory = "256mb"
EOF
